            //
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 27U)) + RotL64(aCarry, 29U)) + 0x7964F861F68BE7F7ULL;
            aOrbiterF = ((aWandererC + RotL64(aCross, 51U)) + 0x7C13D2A1BC749BF2ULL) + aOASaltC[(((511U - aIndex) + 95U)) & S_SALT1];
