            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (((aWandererH + RotL64(aIngress, 21U)) + RotL64(aCarry, 53U)) + 0x7EEA33ACAB3B8E18ULL) + aOASaltC[(((511U - aIndex) + 63U)) & S_SALT1];
