            aOrbiterK = ((aWandererJ + RotL64(aPrevious, 14U)) + 0x4CE28F840634903DULL) + aOASaltD[((aIndex + 277U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xFC968286B809A7D6ULL;
