            aWandererA = aWandererA + ((RotL64(aPrevious, 47U) + aOrbiterG) + RotL64(aOrbiterH, 4U));
            aWandererG = aWandererG ^ (((RotL64(aScatter, 6U) + aOrbiterE) + RotL64(aOrbiterD, 23U)) + aWUSaltD[(((511U - aIndex) + 187U)) & S_SALT1]);
