            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x59594D415C0AF189ULL) + aOUSaltG[(((511U - aIndex) + 408U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x9C7BED90E7C2B847ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE67F46EABD30AE03ULL), 39U);
