            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 5653U)) & S_BLOCK1], 23U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 4481U)) & S_BLOCK1], 34U));
