            //
            aScatter = (RotL64(aPrevious, 19U) ^ RotL64(aCross, 39U)) + (RotL64(aCarry, 3U) + RotL64(aIngress, 54U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = ((aWandererE + RotL64(aPrevious, 50U)) + RotL64(aCarry, 19U)) + 0x2F128D11B6DB1063ULL;
            aOrbiterK = ((aWandererG + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0xD94CD22C91E2F63DULL;
            aOrbiterC = ((aWandererK + RotL64(aIngress, 37U)) + RotL64(aCarry, 5U)) + 0x5EDE03A82A0CFE13ULL;
            aOrbiterE = ((aWandererJ + RotL64(aCross, 3U)) + 0x2F5CB5C5251DA93AULL) + aOASaltD[(((511U - aIndex) + 280U)) & S_SALT1];
            aOrbiterH = ((aWandererI + RotL64(aPrevious, 13U)) + 0x2DE4389ED0CACC17ULL) + aOASaltF[((aIndex + 495U)) & S_SALT1];
            aOrbiterB = ((aWandererH + RotL64(aIngress, 27U)) + 0x57D567DF2F06E2A5ULL) + aOASaltC[((aIndex + 431U)) & S_SALT1];
            aOrbiterF = ((aWandererC + RotL64(aScatter, 43U)) + 0xB257440DA5115749ULL) + aOASaltH[((aIndex + 299U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x3DC1C4920AD95B96ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xB7059FAFC43F6A94ULL;
