            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xBF3BADA193AEDADBULL) + aOUSaltD[(((511U - aIndex) + 131U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0x171A68144DEE6442ULL) ^ aOUSaltC[((aIndex + 474U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x9DE34E614FB552BFULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x3AA3582315E6B4D9ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x0F45F38E147B4B51ULL) ^ aOUSaltE[((aIndex + 385U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x83F901DC9EA18CF1ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x34FADC1071F768FBULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xC43D604064ADCFD0ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xCB21F5DF87B37217ULL), 19U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterC, 53U);
            aIngress = aIngress + (RotL64(aOrbiterD, 22U) ^ aOrbiterE);
            aIngress = aIngress + (RotL64(aOrbiterF, 37U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterK, 29U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererH = aWandererH + (((RotL64(aIngress, 23U) + RotL64(aOrbiterC, 51U)) + aOrbiterD) + RotL64(aCarry, 39U));
            aWandererC = aWandererC ^ (((RotL64(aScatter, 37U) + RotL64(aOrbiterD, 11U)) + aOrbiterE) + aWUSaltE[(((511U - aIndex) + 84U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 43U) + aOrbiterK) + RotL64(aOrbiterF, 42U)) + RotL64(aCarry, 3U));
            aWandererE = aWandererE ^ (((RotL64(aCross, 14U) + RotL64(aOrbiterB, 3U)) + aOrbiterF) + aWUSaltG[(((511U - aIndex) + 505U)) & S_SALT1]);
