            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 12978U)) & S_BLOCK1], 35U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 15628U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 9214U)) & S_BLOCK1], 48U) ^ RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 10005U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 19U) + RotL64(aCarry, 5U)) + (RotL64(aCross, 56U) ^ RotL64(aPrevious, 43U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = ((aWandererA + RotL64(aScatter, 60U)) + RotL64(aCarry, 39U)) + 0x4043B30DE4EED2A8ULL;
            aOrbiterD = ((aWandererF + RotL64(aCross, 39U)) + 0x781CB79C2F929189ULL) + aOASaltA[((aIndex + 357U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 11U)) + 0xC759AEDB3C8BBDDFULL;
            aOrbiterB = ((aWandererD + RotL64(aIngress, 53U)) + RotL64(aCarry, 11U)) + 0x5694E9F7B935DC40ULL;
            aOrbiterA = ((aWandererI + RotL64(aCross, 3U)) + RotL64(aCarry, 53U)) + 0xDBAC464815720621ULL;
            aOrbiterK = ((aWandererC + RotL64(aPrevious, 21U)) + 0x45913E2AA6505EEDULL) + aOASaltB[((aIndex + 267U)) & S_SALT1];
            aOrbiterI = ((aWandererH + RotL64(aScatter, 27U)) + 0x88DDE80E85D032B8ULL) + aOASaltD[(((511U - aIndex) + 386U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x4EA261C6BA1716C8ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x895DA846B5314D39ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x721A5FB477CAEE1BULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x7AB844AED055354EULL) + aOUSaltF[(((511U - aIndex) + 155U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x80E185F161F16EF0ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x85741382694ED8D1ULL), 3U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x42D72D1C715420B3ULL) + aOUSaltE[(((511U - aIndex) + 468U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x7CD947EF3E87D75FULL;
            aOrbiterD = RotL64((aOrbiterD * 0xCDA4374FA886058FULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xD6E2922F010F045DULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0x81263841F385D2DCULL) ^ aOUSaltB[((aIndex + 124U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x2D9ED35825BB6353ULL), 21U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0x55A2246C19C4B03CULL) + aOUSaltG[(((511U - aIndex) + 48U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x31F408E1ECE2CF9BULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBA724122D51B60FDULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x1AF7307B0385D424ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0xB333BF19195F5D15ULL) ^ aOUSaltH[((aIndex + 381U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x668647420E8DBC45ULL), 35U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x75F3F4E76B5E9B58ULL) + aOUSaltA[(((511U - aIndex) + 397U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xB9075BB03D8DEA40ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8552C693226F9131ULL), 47U);
            //
            aIngress = RotL64(aOrbiterB, 13U) ^ aOrbiterJ;
            aIngress = aIngress + (RotL64(aOrbiterI, 36U) ^ aOrbiterF);
            aIngress = aIngress + (RotL64(aOrbiterA, 19U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterD, 57U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((RotL64(aIngress, 39U) + aOrbiterA) + RotL64(aOrbiterK, 13U));
            aWandererD = aWandererD ^ (((RotL64(aScatter, 58U) + aOrbiterJ) + RotL64(aOrbiterA, 19U)) + aWUSaltD[((aIndex + 79U)) & S_SALT1]);
            aWandererC = aWandererC + ((((RotL64(aPrevious, 51U) + RotL64(aOrbiterA, 51U)) + aOrbiterF) + RotL64(aCarry, 19U)) + aWUSaltE[(((511U - aIndex) + 76U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 21U) + aOrbiterB) + RotL64(aOrbiterF, 58U));
            aWandererI = aWandererI + (((RotL64(aPrevious, 29U) + RotL64(aOrbiterF, 3U)) + aOrbiterD) + aWUSaltH[(((511U - aIndex) + 275U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 11U) + aOrbiterI) + RotL64(aOrbiterD, 43U));
            aWandererB = aWandererB + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterI, 37U)) + aOrbiterK) + RotL64(aCarry, 3U)) + aWUSaltC[(((511U - aIndex) + 507U)) & S_SALT1]);
