            aOrbiterF = RotL64((aOrbiterF * 0xDE920681DE39F59FULL), 19U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0x313BA566E8C389ABULL) + aOUSaltE[(((511U - aIndex) + 359U)) & S_SALT1];
