    std::uint64_t *aOUSaltA = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltA;
    std::uint64_t *aOUSaltB = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltB;
    std::uint64_t *aOUSaltC = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltC;
    std::uint64_t *aOUSaltD = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltD;
