    std::uint64_t *aOUSaltG = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltG;
    std::uint64_t *aOUSaltH = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mOrbiterUpdate.mSaltH;
    std::uint64_t *aWUSaltA = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mWandererUpdate.mSaltA;
    std::uint64_t *aWUSaltB = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mWandererUpdate.mSaltB;
    std::uint64_t *aWUSaltC = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mWandererUpdate.mSaltC;
