    std::uint64_t *aWUSaltG = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mWandererUpdate.mSaltG;
    std::uint64_t *aWUSaltH = pWorkSpace->mDomainBundle.mKeyRotateBSalts.mWandererUpdate.mSaltH;
    const std::uint64_t &aKeyRotateBDomainWordIngress = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mIngress;
    const std::uint64_t &aKeyRotateBDomainWordScatter = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mScatter;
    const std::uint64_t &aKeyRotateBDomainWordCross = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mCross;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
