            //
            aCross = (RotL64(aKineticLaneC[((S_BLOCK1 - aIndex + 5939U)) & S_BLOCK1], 35U) ^ RotL64(aKineticLaneA[((S_BLOCK1 - aIndex + 6500U)) & S_BLOCK1], 23U));
            aCross ^= (RotL64(aAetherLaneB[((S_BLOCK1 - aIndex + 7321U)) & S_BLOCK1], 3U) ^ RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 6632U)) & S_BLOCK1], 14U));
