            //
            aScatter = (RotL64(aCross, 5U) ^ RotL64(aIngress, 54U)) ^ (RotL64(aCarry, 39U) + RotL64(aPrevious, 19U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterI = ((aWandererH + RotL64(aIngress, 21U)) + 0xA0D25677E52280E9ULL) + aOASaltD[((aIndex + 87U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aScatter, 6U)) + RotL64(aCarry, 11U)) + 0x26EC8BE6D24C1334ULL) + aOASaltA[((aIndex + 441U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aPrevious, 27U)) + RotL64(aCarry, 47U)) + 0xDEE576A98F77BEB3ULL;
            aOrbiterH = ((aWandererA + RotL64(aCross, 29U)) + 0x82BD65F6C4BE5D4CULL) + aOASaltH[(((511U - aIndex) + 497U)) & S_SALT1];
            aOrbiterC = (aWandererF + RotL64(aPrevious, 41U)) + 0xAD6EE5ABC53AB1C6ULL;
            aOrbiterJ = (aWandererB + RotL64(aScatter, 47U)) + 0x197B884CF50705F3ULL;
            aOrbiterD = (aWandererC + RotL64(aCross, 19U)) + 0x86C748E5888F93BDULL;
            aOrbiterG = (aWandererI + RotL64(aIngress, 13U)) + 0x398550BB77A12946ULL;
            aOrbiterF = ((aWandererD + RotL64(aScatter, 3U)) + 0xEA6D2CD5C60CE461ULL) + aOASaltG[(((511U - aIndex) + 49U)) & S_SALT1];
            aOrbiterE = (aWandererG + RotL64(aPrevious, 54U)) + 0x7682C8B844557A87ULL;
            aOrbiterB = (((aWandererK + RotL64(aCross, 39U)) + RotL64(aCarry, 29U)) + 0xD4193D6C8AF9AF1AULL) + aOASaltE[(((511U - aIndex) + 93U)) & S_SALT1];
            //
            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0x17CE10CD13F98AA1ULL) + aOUSaltA[((aIndex + 53U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xF37DDE823E55C8B7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4662745C3930A18DULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x9C24194995986550ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x1DA989688C6A583BULL) ^ aOUSaltG[((aIndex + 312U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x4544A90FC1CDB2B7ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x7178821595ECF7AFULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x61F34F6B2510AEFBULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4FE204F87DF67245ULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x9CA4BEC91C8C6C63ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x8436F1CED1F6F411ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1721D793AA141F77ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x3054A27634521A18ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x645308ED1264B234ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x0573D71420FCC28BULL), 41U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x42E1F8C86E1FC51EULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x5C779A296AE6F848ULL) ^ aOUSaltD[((aIndex + 33U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x5B776EC9074EF7D3ULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xA49292ADA7862942ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xCCE813AB3763B546ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1C392A2C672884BFULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xBE192649D295543BULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x096C109CF4CADE5AULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0B7E65C0B6ADEA35ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x655C96E8C436EAE8ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0xB503DE7B728A388DULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0EE96E09B7BC8EE7ULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x4DBE4C2D72177B60ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0xEF3D95EE2D36B3C0ULL) ^ aOUSaltH[((aIndex + 212U)) & S_SALT1];
