            aOrbiterD = (((aWandererB + RotL64(aScatter, 47U)) + RotL64(aCarry, 57U)) + 0x7596B5A91F32A5D1ULL) + aOASaltC[(((511U - aIndex) + 152U)) & S_SALT1];
