            aOrbiterG = (((aWandererC + RotL64(aCross, 27U)) + RotL64(aCarry, 11U)) + 0xFC8AD708E99A482EULL) + aOASaltF[(((511U - aIndex) + 275U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 43U)) + 0x7BF434437E3F2605ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0xB3EE14ED6FCA4A25ULL) + aOUSaltA[((aIndex + 36U)) & S_SALT1];
