            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xD9391CF863CC05BEULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x55DE6AAF83C5C22FULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC9C7F750462272F5ULL), 19U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0x2AE46B4F3D1BB78DULL) + aOUSaltE[((aIndex + 286U)) & S_SALT1];
